sect1.programlisting:
IMPORT STD;
DATA15 attachment :=  D'test attachment';
STD.System.Email.SendEmailAttachData( 'me@example.com',
                                  'testing 1,2,3',
                                  'this is a test message',
                                   attachment,
                                  'application/octet-stream',
                                  'attachment.txt');
